#include "dnd_character.h"

#include <algorithm>
#include <array>

namespace dnd_character {

namespace {

std::mt19937& rng() {
    static std::mt19937 generator{std::random_device{}()};
    return generator;
}

}  // namespace

int modifier(int score) {
    const int diff = score - 10;
    return diff / 2 + (diff % 2 < 0);
}

int ability() {
    static const std::uniform_int_distribution<int> die{1, 6};
    std::array<int, 4> rolls{};
    for (auto& roll : rolls) {
        roll = die(rng());
    }
    std::sort(rolls.begin(), rolls.end());
    return rolls[1] + rolls[2] + rolls[3];
}

Character make_character() {
    return Character{
        ability(), ability(), ability(), ability(), ability(), ability(),
        10 + modifier(ability())  // wait — hitpoints uses the character's constitution
    };
}
```

Note: hitpoints must equal 10 + modifier(character.constitution). So compute constitution first. Better to construct it like this:

```cpp
Character make_character() {
    const int constitution = ability();
    return Character{
        ability(),
        ability(),
        constitution,
        ability(),
        ability(),
        ability(),
        10 + modifier(constitution),
    };
}
```

The tests only construct `dnd_character::Character character;` and check the fields. So a default constructor that fills in the values is enough. It's fine to provide both a default constructor and a factory. Keep it simple: in the header, declare `Character make_character();` and give Character a default constructor that calls it? Actually, the tests just do `dnd_character::Character character;`. So a default constructor that initializes the members is enough.

Simplest approach: in the header, define a struct with a default constructor implemented in the cpp:

```cpp
struct Character {
    int strength;
    int dexterity;
    int constitution;
    int intelligence;
    int wisdom;
    int charisma;
    int hitpoints;

    Character();
};
```

And in the cpp:

```cpp
Character::Character()
    : strength{ability()},
      dexterity{ability()},
      constitution{ability()},
      intelligence{ability()},
      wisdom{ability()},
      charisma{ability()},
      hitpoints{10 + modifier(constitution)}
{
}
```

The member initializer list is evaluated in declaration order, so constitution is initialized before hitpoints — good.

Also, the build uses `-Wall -Wextra -Wpedantic -Werror`, so it needs to compile cleanly.

